REQUEST='a05eba8bf496332916d07cfd40a99d698b0cccd83c62e8900cccb091ae05c06b'
def render(key,s):
    compile(s,key,'exec')
    encoded=base64.b64encode(zlib.compress(s.encode('ascii'),9)).decode()
    cmd=f"/usr/bin/timeout 20s /usr/bin/python3 -IBc 'import base64,zlib;exec(zlib.decompress(base64.b64decode(\"{encoded}\")))'"
    if len(cmd)>2048:
        raise ValueError((key,len(cmd)))
    return cmd
def audit(commands):
    evidence={}
    for stage,cmd in commands.items():
        w=['wsl.exe','-d','Ubuntu-20.04','--exec','/home/zhj/.local/bin/hpc5000','exec','--timeout','24','--',cmd]
        r=subprocess.run(w,capture_output=True,timeout=29)
        for stream,raw in (('stdout',r.stdout),('stderr',r.stderr)):
            with (ROOT/f'{stage}_{stream}.bin').open('xb') as f:
                f.write(raw)
        lines=r.stdout.decode('utf-8','replace').splitlines()
        entries=[line[6:] for line in lines if line.startswith('AUDIT ')]
        if r.returncode or len(entries)!=1:
            raise RuntimeError((stage,r.returncode,lines))
        evidence[stage]=json.loads(entries[0])
        print(stage,'PASS',flush=True)
    a,b=evidence['archive'],evidence['rehash']
    assert (a['archive_sha256'],a['archive_bytes'])==(b['archive_sha256'],b['archive_bytes'])
    result=dict(status='FORMAL_CISC_RUI_D_NATIVE_POST_PREDICTION_FREEZE_AUDIT_PASS',
                request_sha256=REQUEST,container='shu-common-25721452-notebook-zrtpob-0',
                server_modified=False,additional_forward=0,scoring_executed=False,
                evidence=evidence)
    with (ROOT/'formal_post_prediction_freeze_receipt_v1.json').open('x',encoding='utf-8') as f:
        json.dump(result,f,indent=2)
        f.write('\n')
    print(json.dumps(dict(status=result['status'], archive=a, pair=evidence['pair'], resources=evidence['state']['resource_records'])),flush=True)
if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--read-only-audit',action='store_true')
    args=parser.parse_args()
    commands={k:render(k,s) for k,s in SOURCES.items()}
    print({k:len(v) for k,v in commands.items()},flush=True)
    if args.read_only_audit:
        audit(commands)
